steps.code:
mutation {
  metafieldDefinitionCreate(definition: {
    name: "Material",
    namespace: "custom",
    key: "material",
    type: "single_line_text_field",
    ownerType: PRODUCT
  }) {
    createdDefinition { id }
    userErrors { field message }
  }
}

mutation {
  metafieldsSet(metafields: [{
    ownerId: "gid://shopify/Product/1",
    namespace: "custom", key: "material",
    value: "algodão", type: "single_line_text_field"
  }]) { userErrors { message } }
}

query {
  product(id: "gid://shopify/Product/1") {
    metafield(namespace: "custom", key: "material") {
      value
      type
    }
  }
}

mutation {
  metafieldDefinitionCreate(definition: {
    name: "Material",
    namespace: "custom",
    key: "material",
    type: "single_line_text_field",
    ownerType: PRODUCT
  }) { createdDefinition { id } userErrors { field message } }
}

mutation {
  metafieldsSet(metafields: [{
    ownerId: "gid://shopify/Product/1",
    namespace: "custom", key: "material",
    value: "algodão orgânico", type: "single_line_text_field"
  }]) { userErrors { message } }
}
